WITH metrics AS (SELECT *, STDDEV_SAMP(credit_limit) OVER (PARTITION BY country) AS country_stddev_samp_credit_limit, ROUND(age / SUM(age) OVER (PARTITION BY country), 4) AS age_share, SUM(credit_limit) OVER (PARTITION BY country ORDER BY age ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_credit_limit, SUM(credit_limit) OVER w_part AS cumulative_credit_limit_2 FROM customers WHERE segment IN ('Consumer', 'SMB', 'Corporate') WINDOW w_part AS (PARTITION BY city, country ORDER BY signup_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, name, country, city, segment, signup_date, credit_limit, age, country_stddev_samp_credit_limit FROM metrics ORDER BY city ASC NULLS LAST;
